import type { Router } from "framework7/types";

const routeRoutes: Router.RouteParameters[] = [
  {
    name: "route",
    path: "/route",
    async({ resolve }) {
      import("@/modules/route/views/RouteView.vue").then((vc) => {
        resolve({ component: vc.default });
      });
    },
  },
];

export default routeRoutes;
