<template>
  <div class="relative h-full w-full overflow-hidden">
    <component
      :is="mapComponent"
      v-if="canRenderMap && mapComponent"
      :stops="stops"
      :api-key="apiKey"
      @stop-tap="(seq: number) => $emit('stop-tap', seq)"
    />

    <div
      v-else
      class="flex h-full w-full flex-col justify-end bg-[radial-gradient(circle_at_30%_20%,rgba(11,115,255,0.12),transparent_55%),linear-gradient(160deg,#eaf1fc,#f5f9ff)]"
    >
      <div class="flex items-center gap-1 overflow-x-auto px-5 pb-6 pt-10">
        <template v-for="(stop, index) in stops" :key="stop.seq">
          <span
            v-if="index > 0"
            class="h-[3px] w-7 shrink-0 rounded-full"
            :style="{ backgroundColor: markerColorFor(stop.status) }"
          />
          <span
            class="flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-[12px] font-[760] text-white shadow-[0_6px_14px_rgba(31,58,107,0.25)]"
            :style="{ backgroundColor: markerColorFor(stop.status) }"
          >
            {{ stop.seq }}
          </span>
        </template>
      </div>
      <p v-if="!stops.length" class="px-5 pb-6 text-[13px] font-[540] text-[#657096]">
        No stops to map yet.
      </p>
    </div>
  </div>
</template>

<script setup lang="ts">
import { markerColorFor } from "../route.visuals";
import type { RouteMapStop } from "../route.types";

defineProps<{ stops: RouteMapStop[] }>();
defineEmits<{ "stop-tap": [seq: number] }>();

const apiKey = import.meta.env.VITE_GOOGLE_MAPS_API_KEY as string | undefined;
const device = getDevice();
const useNative = !!(device.android && device.capacitor);
const canRenderMap = useNative || !!apiKey;

const mapComponent = !canRenderMap
  ? null
  : useNative
    ? defineAsyncComponent(() => import("./RouteMapNative.vue"))
    : defineAsyncComponent(() => import("./RouteMapWeb.vue"));
</script>
