<template>
  <F7Page class="bg-[#f5f9ff]">
    <div
      class="relative w-full overflow-hidden transition-[height] duration-300"
      :class="expanded ? 'h-[80vh]' : 'h-[42vh] min-h-[300px]'"
    >
      <RouteMap :stops="itinerary.mapStops" @stop-tap="onStopTap" />

      <div class="absolute inset-x-0 top-0 z-20 px-4 pt-[calc(env(safe-area-inset-top)+12px)]">
        <RouteSearchOverlay
          v-model="searchTerm"
          :expanded="expanded"
          @toggle-expand="expanded = !expanded"
        />
      </div>
    </div>

    <div
      v-show="!expanded"
      class="relative z-10 -mt-6 min-h-[40vh] rounded-t-3xl bg-[#f5f9ff] px-[18px] pb-[120px] pt-5 shadow-[0_-12px_30px_rgba(31,58,107,0.08)] max-[430px]:px-3.5"
    >
      <div v-if="loading" class="flex justify-center py-10">
        <F7Preloader />
      </div>

      <p v-else-if="isEmpty" class="py-10 text-center text-sm font-[540] text-[#657096]">
        No stops planned for today.
      </p>

      <template v-else>
        <RouteCurrentStopCard
          v-if="itinerary.currentStop"
          :name="itinerary.currentStop.name"
          :address="itinerary.currentStop.address"
          :image-src="partnerImageSrc(itinerary.currentStop.image)"
          :distance-label="distanceLabel"
          :visit-type="PLACEHOLDER_VISIT_TYPE"
        />

        <section v-if="itinerary.upcoming.length" class="mt-6">
          <h2 class="mb-3 text-[16px] font-[820] leading-none text-[#090e24]">Upcoming</h2>
          <div class="flex flex-col gap-2.5">
            <RouteStopRow
              v-for="(stop, index) in itinerary.upcoming"
              :key="stop.ruid"
              :name="stop.name"
              :address="stop.address"
              :image-src="partnerImageSrc(stop.image)"
              :time="placeholderEta(index)"
              variant="upcoming"
              @open="onStopTap(stop.sequence)"
            />
          </div>
        </section>

        <section v-if="itinerary.completed.length" class="mt-6">
          <h2 class="mb-3 text-[16px] font-[820] leading-none text-[#090e24]">Completed</h2>
          <div class="flex flex-col gap-2.5">
            <RouteStopRow
              v-for="stop in itinerary.completed"
              :key="stop.ruid"
              :name="stop.name"
              :address="stop.address"
              :image-src="partnerImageSrc(stop.image)"
              :time="stop.timeLabel"
              variant="completed"
              @open="onStopTap(stop.sequence)"
            />
          </div>
        </section>
      </template>
    </div>

    <div v-show="!expanded" class="fixed bottom-[84px] right-4 z-40">
      <RouteOptimizeButton @optimize="optimizeRoute" />
    </div>
  </F7Page>
</template>

<script setup lang="ts">
import RouteMap from "../components/RouteMap.vue";
import RouteSearchOverlay from "../components/RouteSearchOverlay.vue";
import RouteCurrentStopCard from "../components/RouteCurrentStopCard.vue";
import RouteStopRow from "../components/RouteStopRow.vue";
import RouteOptimizeButton from "../components/RouteOptimizeButton.vue";
import { useRouteItinerary } from "../composables/useRouteItinerary";
import { useDeviceLocation } from "../composables/useDeviceLocation";
import { formatDistance, haversineMeters, placeholderEta, PLACEHOLDER_VISIT_TYPE } from "../route.format";
import { partnerImageSrc } from "../route.visuals";

const { itinerary, searchTerm, loading, isEmpty } = useRouteItinerary();
const { coords } = useDeviceLocation();

const expanded = ref(false);

const distanceLabel = computed(() => {
  const stop = itinerary.value.currentStop;
  if (!stop || stop.lat == null || stop.lng == null || !coords.value) return null;
  return formatDistance(
    haversineMeters(coords.value, { lat: stop.lat, lng: stop.lng }),
  );
});

function onStopTap(sequence: number) {
  void sequence;
}

function optimizeRoute() {
  f7.toast
    .create({ text: "Route optimization coming soon", closeTimeout: 2000 })
    .open();
}
</script>
